from pathlib import Path
import json,html
R=Path('/Users/james/Developer/Hackathon/Design/Presentation/Finn-Keynote-2026-10-16');sc=json.loads((R/'production/cinematic-scenes.json').read_text());plan=json.loads((R/'production/slide-plan.json').read_text())
def el(n):
 s=f'left:{n["x"]}px;top:{n["y"]}px;width:{n["w"]}px;height:{n["h"]}px;'
 if n.get('clip') or n.get('radius'):s+='overflow:hidden;'
 if n.get('radius'):s+=f'border-radius:{n["radius"]}px;'
 if n.get('bg'):s+='background:'+n['bg']+';'
 if n['kind']=='rect':s+='background:'+n['color']+';'
 content=n.get('svg','')
 if n['kind']=='image':
  content=f'<img src="{n["src"]}" alt="">'
  if n.get('video'):content=f'<video muted playsinline preload="none" poster="{n["src"]}" src="videos/{n["video"]}.mp4" aria-label="Finn product demonstration; scripted input"></video>'
 if n['kind']=='group':content=''.join(el(c) for c in n['children'])
 m=html.escape(json.dumps(n.get('motion',{})),quote=True)
 return f'<div class="layer" data-name="{html.escape(n["name"],quote=True)}" data-key="{n["key"]}" data-motion="{m}" style="{s}"'+(f' role="img" aria-label="{html.escape(n["text"],quote=True)}"' if n['kind']=='text' else '')+'>'+content+'</div>'
slides=''.join(f'<section class="slide" style="background:{s["bg"]}" aria-label="Slide {s["number"]}: {html.escape(s["title"],quote=True)}">'+''.join(el(n) for n in s['nodes'])+'</section>' for s in sc)
css='''*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#000;color:white;font-family:-apple-system,BlinkMacSystemFont,sans-serif}#stage{width:1920px;height:1080px;position:absolute;transform-origin:top left;overflow:hidden}.slide{position:absolute;inset:0;display:none;overflow:hidden}.slide.active{display:block}.layer{position:absolute;transform-origin:center;will-change:transform,opacity}.layer svg,.layer img,.layer video{display:block;width:100%;height:100%;object-fit:fill}#controls{position:fixed;bottom:16px;left:50%;transform:translateX(-50%);padding:8px 12px;display:flex;gap:6px;align-items:center;background:#1c1c1ef2;border:1px solid #ffffff20;border-radius:18px;opacity:0;transition:opacity .2s;z-index:50;font-size:13px;white-space:nowrap}body.controls #controls,#controls:focus-within{opacity:1}button,a{font:inherit;color:inherit}button{background:#ffffff12;border:0;border-radius:9px;padding:9px 12px;cursor:pointer}button:hover,button:focus-visible{background:#ffffff25;outline:2px solid #ff2d92}button:disabled{opacity:.3;cursor:default}#count{min-width:56px;text-align:center;font-variant-numeric:tabular-nums}#notes,#help,#grid{display:none;position:fixed;z-index:60;background:#202024fa;border-radius:20px;padding:30px;line-height:1.5;overflow:auto}#notes{right:24px;bottom:90px;width:min(650px,88vw);max-height:70vh;font-size:18px}#notes h2{font-size:25px;margin:0}#notes small{font-size:14px;color:#aaa}#help{inset:12% 18%;font-size:20px}#help a{color:#ff6db0}#grid{inset:0;border-radius:0;grid-template-columns:repeat(3,1fr);gap:24px;padding:50px}#grid.open{display:grid}#grid img{width:100%;display:block}#grid button{padding:0;background:none;text-align:left}#grid span{display:block;padding:8px}#notes.open,#help.open{display:block}#black{display:none;position:fixed;inset:0;background:black;z-index:100}#black.open{display:block}#film{display:none;position:absolute;inset:0;z-index:40;background:#000}#film.open{display:block}body.film-playing #controls{display:none}#film video{width:100%;height:100%;object-fit:contain}#filmClose{position:absolute;right:24px;top:24px;opacity:0}#film:hover #filmClose{opacity:1}#scrub{width:110px;accent-color:#ff2d92}@media(prefers-reduced-motion:reduce){#controls{transition:none}}@media print{body{overflow:visible}#stage{transform:none!important;position:static}.slide{display:block;position:relative;width:1920px;height:1080px;page-break-after:always}#controls,#notes,#grid,#help{display:none!important}}'''
js='''const plan=PLAN,scenes=SCENES;const slides=[...document.querySelectorAll('.slide')],stage=document.querySelector('#stage');let current=0,raf=0,start=0,reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,tracks=[],uiTimer,shared=null,manualTime=null;
function scale(){let k=Math.min(innerWidth/1920,innerHeight/1080);stage.style.transform=`translate(${(innerWidth-1920*k)/2}px,${(innerHeight-1080*k)/2}px) scale(${k})`}addEventListener('resize',scale);scale();
function ease(p){let a=0,b=1,t=.5;for(let i=0;i<12;i++){t=(a+b)/2;let x=3*(1-t)**2*t*.22+3*(1-t)*t*t*.36+t*t*t;if(x<p)a=t;else b=t;}return 3*(1-t)**2*t+3*(1-t)*t*t+t*t*t;}
function value(points,t,fallback=0){if(!points)return fallback;if(t<=points[0][0])return points[0][1];for(let i=1;i<points.length;i++){let [b,y]=points[i],[a,x]=points[i-1];if(t<=b)return x+(y-x)*ease((t-a)/(b-a||1));}return points.at(-1)[1];}
function draw(t){for(const {el,m} of tracks){let x=value(m.x,t),y=value(m.y,t),s=value(m.scale,t,1);el.style.transform=`translate3d(${x}px,${y}px,0) scale(${s})`;el.style.opacity=value(m.opacity,t,1);if(m.width)el.style.width=value(m.width,t)+'px';}if(shared){let p=ease(Math.min(1,t/1.35)),x=shared.x*(1-p),y=shared.y*(1-p),s=shared.s+(1-shared.s)*p;shared.el.style.transform=`translate3d(${x}px,${y}px,0) scale(${s})`;if(p>=1)shared=null;}document.querySelector('#scrub').value=t;}
function frame(now){let t=(now-start)/1000;draw(t);if(t<Math.max(8,scenes[current].duration))raf=requestAnimationFrame(frame);}
function enter(i,continuity=true){cancelAnimationFrame(raf);let old=slides[current].querySelector('[data-name="iPhone"]'),oldInfo=old&&slides[current].classList.contains('active')?{x:parseFloat(old.style.left),y:parseFloat(old.style.top),w:parseFloat(old.style.width),h:parseFloat(old.style.height)}:null;slides.forEach(s=>s.querySelectorAll('video').forEach(v=>v.pause()));current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,j)=>s.classList.toggle('active',j===current));const slide=slides[current];tracks=[...slide.querySelectorAll('[data-motion]')].map(el=>({el,m:JSON.parse(el.dataset.motion)}));shared=null;let next=slide.querySelector('[data-name="iPhone"]');if(continuity&&!reduce&&oldInfo&&next){let nw=parseFloat(next.style.width),nh=parseFloat(next.style.height);shared={el:next,x:oldInfo.x-parseFloat(next.style.left)+(oldInfo.w-nw)/2,y:oldInfo.y-parseFloat(next.style.top)+(oldInfo.h-nh)/2,s:oldInfo.w/nw};tracks=tracks.filter(t=>t.el!==next);}draw(reduce?99:0);start=performance.now();if(!reduce)raf=requestAnimationFrame(frame);slide.querySelectorAll('video').forEach(v=>{v.currentTime=0;if(!reduce)v.play().catch(()=>{});});document.querySelector('#count').textContent=`${current+1} / ${slides.length}`;let p=plan.slides[current];document.querySelector('#notes').innerHTML=`<h2>${String(current+1).padStart(2,'0')} · ${p.title}</h2><p>${p.speaker_notes}</p><small>${p.seconds}s · ${p.motion}</small>`;location.hash=current+1;document.title=`Finn · ${current+1} / ${slides.length}`;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===slides.length-1;}
function ui(){document.body.classList.add('controls');clearTimeout(uiTimer);uiTimer=setTimeout(()=>document.body.classList.remove('controls'),2300)}addEventListener('pointermove',ui);
function toggle(id){document.querySelector(id).classList.toggle('open')}
function media(){slides[current].querySelectorAll('video').forEach(v=>v.paused?v.play():v.pause())}
function full(){document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen().catch(()=>{})}
function film(){const box=document.querySelector('#film'),v=box.querySelector('video');box.classList.add('open');document.body.classList.add('film-playing');document.activeElement?.blur();slides[current].querySelectorAll('video').forEach(x=>x.pause());v.currentTime=0;v.play().catch(()=>{});v.onended=()=>{box.classList.remove('open');document.body.classList.remove('film-playing');enter(1,false)}}
document.querySelector('#prev').onclick=()=>enter(current-1);document.querySelector('#next').onclick=()=>enter(current+1);document.querySelector('#replay').onclick=()=>enter(current,false);document.querySelector('#media').onclick=media;document.querySelector('#presenter').onclick=()=>toggle('#notes');document.querySelector('#overview').onclick=()=>toggle('#grid');document.querySelector('#full').onclick=full;document.querySelector('#helpbutton').onclick=()=>toggle('#help');document.querySelector('#filmButton').onclick=film;document.querySelector('#filmClose').onclick=()=>{document.querySelector('#film video').pause();document.body.classList.remove('film-playing');toggle('#film')};document.querySelector('#motion').onclick=()=>{reduce=!reduce;document.querySelector('#motion').textContent=reduce?'Motion off':'Motion on';enter(current,false)};document.querySelector('#motion').textContent=reduce?'Motion off':'Motion on';document.querySelector('#scrub').oninput=e=>{cancelAnimationFrame(raf);shared=null;draw(Number(e.target.value));slides[current].querySelectorAll('video').forEach(v=>{v.pause();if(Number.isFinite(v.duration))v.currentTime=Math.min(Number(e.target.value),v.duration-.05);});};
document.querySelector('#grid').innerHTML=plan.slides.map((s,i)=>`<button data-i="${i}"><img loading="lazy" src="preview/${String(i+1).padStart(2,'0')}.png"><span>${i+1} · ${s.title}</span></button>`).join('');document.querySelectorAll('#grid button').forEach(b=>b.onclick=()=>{toggle('#grid');enter(Number(b.dataset.i),false)});addEventListener('keydown',e=>{if(document.body.classList.contains('film-playing')){if(e.key==='Escape'){document.querySelector('#film video').pause();document.querySelector('#film').classList.remove('open');document.body.classList.remove('film-playing')}else if(e.key===' '){e.preventDefault();const v=document.querySelector('#film video');v.paused?v.play():v.pause()}return;}if(e.target.tagName==='INPUT')return;if(['ArrowRight','ArrowLeft',' ','PageDown','PageUp','Home','End'].includes(e.key))e.preventDefault();if(['ArrowRight',' ','PageDown'].includes(e.key))enter(current+1);if(['ArrowLeft','PageUp'].includes(e.key))enter(current-1);if(e.key==='Home')enter(0,false);if(e.key==='End')enter(slides.length-1,false);let k=e.key.toLowerCase();if(k==='r')enter(current,false);if(k==='p')media();if(k==='n')toggle('#notes');if(k==='g')toggle('#grid');if(k==='b')toggle('#black');if(k==='f')full();if(e.key==='Escape'){document.querySelectorAll('#grid,#help,#notes,#black').forEach(x=>x.classList.remove('open'));document.querySelector('#film video').pause();document.querySelector('#film').classList.remove('open');}});enter(Math.max(0,Number(location.hash.slice(1)||1)-1),false);ui();'''.replace('PLAN',json.dumps(plan,ensure_ascii=False)).replace('SCENES',json.dumps([{'duration':s['duration']} for s in sc]))
doc='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finn</title><style>'+css+'</style><body><main id="stage">'+slides+'<div id="film"><video controls playsinline preload="none" poster="production/film/film-poster.jpg" src="videos/finn-opening-film.mp4"></video><button id="filmClose">Close film</button></div></main><nav id="controls" aria-label="Presentation controls"><button id="prev" aria-label="Previous slide">←</button><span id="count"></span><button id="next" aria-label="Next slide">→</button><button id="replay">Replay</button><button id="media">Play / pause</button><button id="filmButton">Opening film</button><button id="overview">Slides</button><button id="presenter">Notes</button><button id="motion">Motion on</button><input id="scrub" aria-label="Motion timeline" type="range" min="0" max="8" step=".05" value="0"><button id="full">Full screen</button><button id="helpbutton">Help</button></nav><aside id="notes"></aside><aside id="grid"></aside><div id="black"></div><aside id="help"><h1>Finn · Rehearsal controls</h1><p>Arrows / Space: next or previous scene<br>R: replay choreography · P: play or pause demo<br>N: notes · G: overview · F: full screen<br>B: black screen · Escape: close overlays</p><p>Drag the motion timeline to inspect individual builds. Use Motion off for a static presentation. The one-minute film replaces the first slide: total running order 11:45.</p><p><a href="speaker-notes.html" target="_blank">Presenter script</a></p><p>Product scenes use generated footage and scripted coaching. Matching Vision landmarks drive the video preview; the film is a fictional use case, not an accuracy study. Official Apple bezels and SF Pro typography. Video originals: 720p.</p></aside><script>'+js+'</script></body></html>'
(R/'index.html').write_text(doc)
print('Cinematic deck built',len(doc),'bytes')
